from socket_diagnostic_preservation import without_socket_diagnostic

def without_helper_retirement(source):
    source = without_socket_diagnostic(source)
    for reviewed, original in REPLACEMENTS:
        if source.count(reviewed) != 1:
            raise ValueError('Changed or duplicate helper retirement block')
        source = source.replace(reviewed, original, 1)
    return source
